definition.script:
var dataInput = input.get('data');
var groupByFields = input.get('groupBy') || '';
var aggregateField = input.get('aggregateField') || '';
var aggregateFunction = input.get('aggregateFunction') || 'count';
var includeDetails = input.get('includeDetails') === 'true';

if (!dataInput) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'Data input is required');
    output.set('Result', '[]');
    tags.trigger('error');
} else {
    try {
        var data = json.parse(dataInput);
        if (!Array.isArray(data)) {
            throw new Error('Input must be a JSON array');
        }

        var groupFields = groupByFields ? groupByFields.split(',').map(function(f) { return f.trim(); }) : [];

        function getVal(obj, path) {
            if (!path) return obj;
            var parts = path.split('.');
            var val = obj;
            for (var i = 0; i < parts.length; i++) {
                if (val === null || val === undefined) return undefined;
                val = val[parts[i]];
            }
            return val;
        }

        function getGroupKey(item) {
            if (groupFields.length === 0) return '_all_';
            var keyParts = [];
            for (var i = 0; i < groupFields.length; i++) {
                var val = getVal(item, groupFields[i]);
                keyParts.push(val === undefined ? 'undefined' : String(val));
            }
            return keyParts.join('|');
        }

        var groups = {};
        var groupData = {};

        for (var i = 0; i < data.length; i++) {
            var item = data[i];
            var key = getGroupKey(item);

            if (!groups[key]) {
                groups[key] = [];
                groupData[key] = {};
                for (var g = 0; g < groupFields.length; g++) {
                    groupData[key][groupFields[g]] = getVal(item, groupFields[g]);
                }
            }

            var aggVal = aggregateField ? getVal(item, aggregateField) : 1;
            groups[key].push(aggVal);
        }

        function aggregate(values, func) {
            var nums = values.filter(function(v) { return typeof v === 'number' && !isNaN(v); });

            switch (func) {
                case 'sum':
                    var sum = 0;
                    for (var i = 0; i < nums.length; i++) sum += nums[i];
                    return sum;
                case 'avg':
                case 'average':
                    if (nums.length === 0) return 0;
                    var total = 0;
                    for (var i = 0; i < nums.length; i++) total += nums[i];
                    return total / nums.length;
                case 'min':
                    if (nums.length === 0) return null;
                    var min = nums[0];
                    for (var i = 1; i < nums.length; i++) if (nums[i] < min) min = nums[i];
                    return min;
                case 'max':
                    if (nums.length === 0) return null;
                    var max = nums[0];
                    for (var i = 1; i < nums.length; i++) if (nums[i] > max) max = nums[i];
                    return max;
                case 'first':
                    return values.length > 0 ? values[0] : null;
                case 'last':
                    return values.length > 0 ? values[values.length - 1] : null;
                case 'collect':
                    return values;
                case 'count':
                default:
                    return values.length;
            }
        }

        var results = [];
        var keys = Object.keys(groups);

        for (var k = 0; k < keys.length; k++) {
            var key = keys[k];
            var row = {};

            var gd = groupData[key];
            var gdKeys = Object.keys(gd);
            for (var g = 0; g < gdKeys.length; g++) {
                row[gdKeys[g]] = gd[gdKeys[g]];
            }

            var aggResult = aggregate(groups[key], aggregateFunction);
            row[aggregateFunction + '_' + (aggregateField || 'count')] = aggResult;
            row['_count'] = groups[key].length;

            if (includeDetails) {
                row['_values'] = groups[key];
            }

            results.push(row);
        }

        var grandTotal = 0;
        for (var r = 0; r < results.length; r++) {
            var val = results[r][aggregateFunction + '_' + (aggregateField || 'count')];
            if (typeof val === 'number') grandTotal += val;
        }

        output.set('Result', json.stringify(results));
        output.set('ResultArray', results);
        output.set('GroupCount', results.length);
        output.set('TotalRows', data.length);
        output.set('GrandTotal', grandTotal);
        output.set('HasErrors', false);
        output.set('ErrorMessage', '');

        log.info('Pivot: ' + data.length + ' rows -> ' + results.length + ' groups');
        tags.trigger('success');

    } catch (ex) {
        log.error('Pivot failed: ' + ex.message);
        output.set('HasErrors', true);
        output.set('ErrorMessage', ex.message);
        output.set('Result', '[]');
        tags.trigger('error');
    }
}
